def content_digest(record):
    payload = {key: value for key, value in record.items() if key != "content_digest"}
    return hashlib.sha256(
        json.dumps(
            payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True
        ).encode("utf-8")
    ).hexdigest()

